'use strict';

// Factory RackUltra (UltraFX) library states captured from Director 2.12 (recalled into UFX units 1–8, 2026-11-02).
const ULTRAFX_LIBRARY_STATES={"Spaces Reverb":{"480 Large":"","480 Medium":"","Brass Hall":"","Bright Chamber":"","Cathedral":"","Choral HF Hall":"","Drum Hall":"","Gated Snare Hall":"","Large Drum Room":"","Large Natural Hall":"","Medium Bright Hall":"","Medium Club":"","Medium Dark Hall":"","Medium Dense Hall":"","Musical Theatre":"","Perc Room":"","Piano Room":"","Room Mic":"","Small Bright Hall":"","Small Church":"","Small Club":"","Small Dark Hall":"","Small Dense Hall":"","Small Natural Hall":"","Vintage Hall":"","Vox Bright Hall":"","Vox Intimate":"","Vox Small Hall":"","Vox Small Theatre":"","Vox Studio":"","Warm Room":"","Wood Hall":"","Wood Room":"","Large Bright Hall":"","Large Dark Hall":"","Piano Hall":"","Small Wide Hall":"","Strings":""},"Plate Reverb":{"Plate 140":"","Plate AcGuitar":"","Plate Big Kit":"","Plate Brass":"","Plate Dark Glue":"","Plate Dark Strings":"","Plate Dark Vox":"","Plate Drum Chrome":"","Plate Drums":"","Plate Echo":"","Plate Gold":"","Plate Penryn Plate":"","Plate Percussion":"","Plate Snare Chrome":"","Plate Snare Impact":"","Plate Tight Amb":"","Plate Vocal Plate":"","Plate Vox Grit":"","Plate Vox Intimate":"","Plate Vox Large":""},"Vocal Tuner":{"Tuner Chromatic":"","Tuner Fast":"","Tuner Soft":""},"Vocal Gridder":{"Gridder Fast":"","Gridder Soft":""},"Vocal Shifter":{"Shifter 12Down 5Up":"","Shifter 5Down 3Up":"","Shifter Doubler 1":"","Shifter Doubler 2":"","Shifter Older":"","Shifter Younger":""},"Vocal Harmoniser 2":{"Dual Harmony Above":"","Dual Harmony Below":"","Dual Thicken":"","Dual Thirds":""},"Vocal Harmoniser 4":{"Quad Full Harmony":"","Quad Thicken":""},"MIDI Harmoniser":{"Midi Mono Fast":"","Midi Mono Slow":"","Midi Poly Narrow":"","Midi Poly Wide":""},"Amp & Cab Distortion":{"AmpCab Bass":"","AmpCab Drums":"","AmpCab Heavy Gtr":"","AmpCab Light Gtr":"","AmpCab Percussion":"","AmpCab Shout Vox":""},"Saturator":{"Saturator Bass":"","Saturator Bus":"","Saturator Drums":"","Saturator Perc":"","Saturator Vocals":""},"Rhythm Delay":{"Advanced Loosen up":"","Advanced PingPong":"","Advanced Shimmer":"","Advanced Slap Back":"","Advanced Speed up":"","Advanced Swell LR":"","Advanced Thick Vox":"","Simple 4 8ths":"","Simple Ping Pong":"","Simple Vox Swell":""},"Empty Rack":{"Empty Rack":""}};

// RackUltra units 1–8 are `AHFX Manager NN` records (246-byte state after the label: discriminator 06 03 00,
// engine id at +3..4, 17-byte preset name at +5). A factory library Recall in Director rewrites only that
// unit's record (full-scene diff), so loading the captured state is equivalent to a Recall. Loading switches
// the engine, so the unit's own engine-specific editors follow the new engine afterwards.
const ULTRAFX_STATE_LENGTH=246;
function ultrafxRecord(unit){
  const dat=state.current?.stage?.datBytes;if(!dat)return null;
  const r=ipParseRecord(dat,`AHFX Manager ${String(unit).padStart(2,'0')}`,ULTRAFX_STATE_LENGTH);
  return r&&dat[r.stateStart]===0x06?r:null;
}
function ultrafxUnitName(unit){
  const r=ultrafxRecord(unit);if(!r)return null;let s='';
  for(let i=5;i<22;i++){const c=state.current.stage.datBytes[r.stateStart+i];if(!c)break;s+=String.fromCharCode(c);}
  return s.trim();
}
function ultrafxFindPreset(name){for(const [e,ps] of Object.entries(ULTRAFX_LIBRARY_STATES))if(ps[name])return {engine:e,hex:ps[name]};return null;}
function loadUltraFxPreset(unit,name){
  const p=ultrafxFindPreset(name),r=ultrafxRecord(Number(unit));if(!p||!r)return false;
  const b=dynHexBytes(p.hex);if(b.length!==ULTRAFX_STATE_LENGTH)return false;
  state.current.stage.datBytes.set(b,r.stateStart);
  if(typeof ahfxRefresh==='function')ahfxRefresh();markStageDirty();return true;
}
function renderUltraFxLibrary(){
  const host=$('#tabFx');if(!host||!state.current?.stage)return;
  let root=$('#ultraFxLib');if(!root){root=document.createElement('section');root.className='panel';root.id='ultraFxLib';host.insertBefore(root,host.children[1]||null);}
  const units=Array.from({length:8},(_,i)=>i+1).filter(u=>ultrafxRecord(u));
  if(!units.length){root.innerHTML='<div class="notice warn">No RackUltra (AHFX Manager) records in this scene.</div>';return;}
  const opts=Object.entries(ULTRAFX_LIBRARY_STATES).map(([e,ps])=>`<optgroup label="${escapeHtml(e)}">${Object.keys(ps).map(n=>`<option>${escapeHtml(n)}</option>`).join('')}</optgroup>`).join('');
  root.innerHTML=`<div class="manager-head inline"><h2>RackUltra units</h2><span class="confidence verified">FACTORY LIBRARY · CAPTURED</span></div>
    <div class="notice">Loads a factory RackUltra preset (and its engine) into a UFX unit exactly as Director's library Recall does.</div>
    ${units.map(u=>`<div class="peq-field"><span>UFX ${u} <small>${escapeHtml(ultrafxUnitName(u)||'')}</small></span><div><select data-uu="${u}">${opts}</select> <button class="btn" type="button" data-uload="${u}">Load</button></div></div>`).join('')}`;
  for(const u of units){
    const sel=root.querySelector(`select[data-uu="${u}"]`),cur=ultrafxUnitName(u);if(ultrafxFindPreset(cur))sel.value=cur;
    root.querySelector(`[data-uload="${u}"]`).onclick=()=>{const ok=loadUltraFxPreset(u,sel.value);toast(ok?`UFX ${u}: loaded ${sel.value}.`:'UFX unit record not found or wrong shape.',!ok);renderFx();};
  }
}
const renderFxBeforeUltraFxLib=renderFx;
renderFx=function(){renderFxBeforeUltraFxLib();renderUltraFxLibrary();};
